// Generate weekly content plan
const approvedContent = $input.all()[0].json || [];
const portfolioCompanies = $input.all()[1].json || [];
const industryNews = $input.all()[2].json || [];

// Get current date and next week's date range
const now = new Date();
const nextWeekStart = new Date(now);
nextWeekStart.setDate(now.getDate() + 1); // Start from tomorrow

const nextWeekEnd = new Date(now);
nextWeekEnd.setDate(now.getDate() + 7); // End one week from today

// Format date range for display
const dateRangeString = `${nextWeekStart.toLocaleDateString()} - ${nextWeekEnd.toLocaleDateString()}`;

// Filter content scheduled for next week
const nextWeekContent = approvedContent.filter(content => {
  const publishDate = new Date(content.publishDate);
  return publishDate >= nextWeekStart && publishDate <= nextWeekEnd;
});

// Sort by publish date
nextWeekContent.sort((a, b) => new Date(a.publishDate) - new Date(b.publishDate));

// Prepare portfolio company updates
const portfolioUpdates = portfolioCompanies
  .filter(company => company.recentMilestone && company.shareOnSocial === 'Yes')
  .map(company => ({
    type: 'Portfolio Update',
    title: `${company.name} - ${company.recentMilestone}`,
    company: company.name,
    content: `We're excited to share that our portfolio company ${company.name} has ${company.recentMilestone}. ${company.milestoneDetails || ''}`,
    suggestedDate: new Date(nextWeekStart.getTime() + Math.random() * (nextWeekEnd.getTime() - nextWeekStart.getTime())).toISOString().split('T')[0],
    platforms: company.preferredPlatforms || 'LinkedIn,Twitter',
    tags: company.tags || '',
    url: company.website || '',
    imageUrl: company.logoUrl || ''
  }));

// Prepare industry news shares
const newsShares = industryNews
  .slice(0, 3) // Limit to 3 news items
  .map(news => ({
    type: 'Industry News',
    title: news.title,
    content: `Interesting read: ${news.title}. ${news.summary || ''}`,
    suggestedDate: new Date(nextWeekStart.getTime() + Math.random() * (nextWeekEnd.getTime() - nextWeekStart.getTime())).toISOString().split('T')[0],
    platforms: 'LinkedIn,Twitter',
    tags: news.tags || '',
    url: news.url || '',
    imageUrl: news.imageUrl || ''
  }));

// Combine all content
const weeklyPlan = {
  planDate: now.toISOString(),
  dateRange: dateRangeString,
  scheduledContent: nextWeekContent,
  portfolioUpdates,
  newsShares,
  totalPosts: nextWeekContent.length + portfolioUpdates.length + newsShares.length
};

return { json: weeklyPlan };

