// Prepare portfolio updates for content calendar
const weeklyPlan = $input.item.json;
const portfolioUpdates = weeklyPlan.portfolioUpdates || [];

// Format updates for content calendar
const calendarItems = portfolioUpdates.map(update => ({
  json: {
    title: update.title,
    type: update.type,
    content: update.content,
    publishDate: update.suggestedDate,
    platforms: update.platforms,
    tags: update.tags,
    url: update.url,
    imageUrl: update.imageUrl,
    status: 'Draft',
    published: false,
    createdDate: new Date().toISOString(),
    author: 'Automation System',
    notes: 'Automatically generated from portfolio milestone'
  }
}));

return calendarItems;

// Prepare news shares for content calendar
const weeklyPlan = $input.item.json;
const newsShares = weeklyPlan.newsShares || [];

// Format news for content calendar
const calendarItems = newsShares.map(news => ({
  json: {
    title: news.title,
    type: news.type,
    content: news.content,
    publishDate: news.suggestedDate,
    platforms: news.platforms,
    tags: news.tags,
    url: news.url,
    imageUrl: news.imageUrl,
    status: 'Draft',
    published: false,
    createdDate: new Date().toISOString(),
    author: 'Automation System',
    notes: 'Automatically generated from industry news'
  }
}));

return calendarItems;

// Check for posts due for publishing
const pendingPosts = $input.item.json;

// If no pending posts, return empty
if (!pendingPosts || pendingPosts.length === 0) {
  return { json: { hasDuePosts: false } };
}

// Get current time
const now = new Date();

// Find posts due for publishing (scheduled within the next hour)
const duePosts = pendingPosts.filter(post => {
  const publishDate = new Date(post.publishDate);

  // Check if publish date is in the past or within the next hour
  const timeDiff = publishDate.getTime() - now.getTime();
  return timeDiff <= 3600000 && timeDiff > -86400000; // Between 1 hour in future and 1 day in past
});

// If no due posts, return empty
if (duePosts.length === 0) {
  return { json: { hasDuePosts: false } };
}

// Return the due posts
return {
  json: {
    hasDuePosts: true,
    duePosts: duePosts
  }
};

// Prepare posts for publishing
const data = $input.item.json;
const duePosts = data.duePosts || [];

// Return array of posts to process individually
return duePosts.map(post => ({ json: post }));

// Process news API response
const response = $input.item.json;
const articles = response.articles || [];

// Format articles for storage
const formattedArticles = articles.map(article => ({
  title: article.title,
  source: article.source.name,
  author: article.author,
  url: article.url,
  publishedDate: article.publishedAt,
  summary: article.description,
  content: article.content,
  imageUrl: article.urlToImage,
  tags: 'industry news, venture capital',
  relevance: 'medium',
  shared: false,
  addedDate: new Date().toISOString(),
  id: `NEWS-${Date.now()}-${Math.floor(Math.random() * 1000)}`
}));

return formattedArticles.map(article => ({ json: article }));

