// Generate social media analytics report
const publishedContent = $input.item.json || [];

// Get date range for the report (last 7 days)
const now = new Date();
const lastWeek = new Date(now);
lastWeek.setDate(now.getDate() - 7);

// Format date range for display
const dateRangeString = `${lastWeek.toLocaleDateString()} - ${now.toLocaleDateString()}`;

// Filter content published in the last week
const recentContent = publishedContent.filter(content => {
  const publishDate = new Date(content.publishedDate);
  return publishDate >= lastWeek && publishDate <= now;
});

// Count posts by platform
const platformCounts = {};
recentContent.forEach(content => {
  const platforms = content.publishedPlatforms || content.platforms || '';
  platforms.split(',').forEach(platform => {
    const p = platform.trim();
    if (p) {
      platformCounts[p] = (platformCounts[p] || 0) + 1;
    }
  });
});

// Count posts by type
const typeCounts = {};
recentContent.forEach(content => {
  const type = content.type || 'Other';
  typeCounts[type] = (typeCounts[type] || 0) + 1;
});

// Identify top performing content (mock data - in real implementation, this would come from social media APIs)
const topContent = recentContent.map(content => ({
  ...content,
  engagement: Math.floor(Math.random() * 100),
  likes: Math.floor(Math.random() * 50),
  shares: Math.floor(Math.random() * 20),
  comments: Math.floor(Math.random() * 10),
  impressions: Math.floor(Math.random() * 1000)
}));

// Sort by engagement
topContent.sort((a, b) => b.engagement - a.engagement);

// Create analytics report
const analyticsReport = {
  reportDate: now.toISOString(),
  dateRange: dateRangeString,
  totalPosts: recentContent.length,
  platformDistribution: JSON.stringify(platformCounts),
  typeDistribution: JSON.stringify(typeCounts),
  topContent: topContent.slice(0, 3),
  allContent: recentContent
};

return { json: analyticsReport };

